// Curation manifest for the portfolio image set — the single source of truth.
//
// Each entry: source (path relative to the repo root), category, role (hero|gallery),
// destination filename (written under public/assets/portfolio/<category>/), and
// bilingual alt text.
//
// Consumed by:
//   scripts/optimize-portfolio-images.mjs   -> writes public/assets/portfolio/**
//   scripts/generate-portfolio-data.mjs     -> writes src/lib/portfolio-data.ts
// Run them in that order; the second measures the files the first produced.
//
// 2026-08 refresh: the whole shoot was re-edited onto a consistent warm-grey studio
// background and re-imported from SKAT-Enhanced/ (design-source, gitignored). Every
// image in that folder is published. Destination names carry a -v2 suffix because
// /assets/* is served immutable for a year (next.config.ts) with non-hashed names —
// reusing the previous filenames would have served the old photos from cache.
//
// Alt text names the client brand where it is legible on the pack.

const SOURCE_ROOT = 'SKAT-Enhanced'
const KASA = `${SOURCE_ROOT}/Display-Kasa`
const PODOV = `${SOURCE_ROOT}/Display-Podov`
const TRAY = `${SOURCE_ROOT}/Tray`
const FOODS = `${SOURCE_ROOT}/Foods`
const ALCOHOL = `${SOURCE_ROOT}/Alcohol_BIB`
const COSMETICS = `${SOURCE_ROOT}/Cosmetics-Pharmacy`
const OTHER = `${SOURCE_ROOT}/Other`

// 2026-08-30 addition: 29 further enhanced photographs, supplied in a sibling
// enhanced-display/ folder rather than in SKAT-Enhanced/.
//
// REPRODUCIBILITY CAVEAT — read before running the optimizer.
// This path is local-only and is NOT present on other machines, exactly like
// SKAT-Enhanced/ above. optimize-portfolio-images.mjs validates that every
// `source` exists and aborts the whole run if any is missing, so it cannot
// currently run for ANY entry in this manifest — not these, and not the 123
// that came before them. The committed JPEGs under public/assets/portfolio/
// are therefore the only reproducible artefact of that step.
// generate-portfolio-data.mjs is unaffected: it measures the committed files
// and never reads `source`.
// Resolving this needs a decision: either archive these originals alongside
// wherever SKAT-Enhanced/ is kept and document that requirement, or decouple
// validation from local-only source folders.
const ENHANCED = '../enhanced-display'

// Bilingual labels for the pos-displays gallery's `group` slugs (see entries
// below). Centralized here so every entry only ever references a slug —
// never duplicates label text — which is what keeps a typo'd label from
// silently rendering as a second, near-identical heading on the live page.
// generate-portfolio-data.mjs resolves each entry's `group` through this
// table and throws on an unknown slug.
export const POS_GROUP_LABELS = {
  'floor-displays': { label: 'Floor Displays', labelBg: 'Подови дисплеи' },
  'counter-displays': { label: 'Counter Displays', labelBg: 'Дисплеи за каса' },
  'shelf-ready-trays': { label: 'Shelf-Ready Trays', labelBg: 'Дисплей тарелки' },
}

